import{_ as a,o as e,c as r,ag as i}from"./chunks/framework.ePeAWSvT.js";const b=JSON.parse('{"title":"关于我","description":"","frontmatter":{},"headers":[],"relativePath":"about.md","filePath":"about.md","lastUpdated":1786688709000}'),l={name:"about.md"};function o(n,t,d,s,h,c){return e(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="关于我" tabindex="-1">关于我 <a class="header-anchor" href="#关于我" aria-label="Permalink to &quot;关于我&quot;">​</a></h1><p>你好，我是林乐珊（Leshan Lin），华南农业大学计算机科学与技术专业本科生，预计 2028 年毕业。</p><p>我希望自己做的不只是“能运行的代码”，而是能够解释、验证和复现的技术工作。目前主要关注深度学习、AI for Science 和后端工程。</p><h2 id="研究与实践方向" tabindex="-1">研究与实践方向 <a class="header-anchor" href="#研究与实践方向" aria-label="Permalink to &quot;研究与实践方向&quot;">​</a></h2><ul><li>物理约束深度学习与地球物理预测</li><li>Transformer 与长时序地震波场预测</li><li>NLP 主题建模和跨文化文本分析</li><li>FastAPI、Celery、Redis 与 PostgreSQL 后端系统</li><li>RAG、结构化输出与 LLM 应用工程</li></ul><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to &quot;技术栈&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类别</th><th>技术</th></tr></thead><tbody><tr><td>深度学习</td><td>PyTorch, Transformers, CNN, Attention, DDP</td></tr><tr><td>数据分析</td><td>NumPy, pandas, scikit-learn, Matplotlib</td></tr><tr><td>后端工程</td><td>FastAPI, Celery, Redis, PostgreSQL, Docker Compose</td></tr><tr><td>编程语言</td><td>Python, Java, C/C++</td></tr></tbody></table><h2 id="我怎样做项目" tabindex="-1">我怎样做项目 <a class="header-anchor" href="#我怎样做项目" aria-label="Permalink to &quot;我怎样做项目&quot;">​</a></h2><ol><li>先定义问题、数据划分和可以被反驳的实验假设。</li><li>用最小实现验证数据流和张量形状。</li><li>记录失败、限制和环境差异，不用不可靠指标包装结果。</li><li>用 README、测试和复现说明把工作交给下一位读者。</li></ol><h2 id="联系方式" tabindex="-1">联系方式 <a class="header-anchor" href="#联系方式" aria-label="Permalink to &quot;联系方式&quot;">​</a></h2><ul><li>GitHub：<a href="https://github.com/isLLccu" target="_blank" rel="noreferrer">isLLccu</a></li><li>Email：<a href="mailto:1467377489@stu.scau.edu.cn" target="_blank" rel="noreferrer">1467377489@stu.scau.edu.cn</a></li><li>Location：Guangzhou, China</li></ul><p>这个博客践行 <strong>Learning by Teaching</strong>：通过解释迫使自己理解得更准确，也把成长过程保留下来。</p>',12)])])}const _=a(l,[["render",o]]);export{b as __pageData,_ as default};
